// Tracks-menu link. OpenStreetMap presets bring their real surroundings along (&osm=).
export function trackHref( track ) {

	if ( ! track.map ) return 'index.html';
	return 'index.html?map=' + track.map + ( track.osm ? '&osm=' + track.osm : '' );

}
